"""Presentation-only enhancement for The Meeting v2.

Uses a real generated tattoo-shop backroom image as the room and layers a more
alive cellular M4 presence over the existing Meeting runtime without touching
voice, reasoning, persistence, or endpoints.
"""

ROOM_JPEG_B64 = """"""

VISUAL_CSS = f'''
<style id="m4-presentation-v4">
html,body{{background:#080806!important}}
.room{{background-image:linear-gradient(180deg,rgba(7,7,6,.12),rgba(7,7,6,.18) 52%,rgba(7,7,6,.72) 84%,rgba(7,7,6,.94)),url("data:image/jpeg;base64,{ROOM_JPEG_B64}")!important;background-size:cover!important;background-position:center center!important;perspective:1200px}}
.room:before{{content:''!important;position:absolute!important;inset:0!important;background:radial-gradient(circle at 50% 42%,transparent 0 22%,rgba(8,8,7,.12) 44%,rgba(4,4,4,.42) 100%)!important;filter:none!important;z-index:0!important}}
.room:after{{content:''!important;position:absolute!important;left:0!important;right:0!important;bottom:0!important;height:28%!important;background:linear-gradient(180deg,transparent,rgba(5,5,5,.86))!important;opacity:1!important;z-index:1!important}}
.grain{{opacity:.11!important;mix-blend-mode:screen!important}}
.presence{{z-index:3!important;width:min(58vw,470px)!important;height:min(58vw,470px)!important;filter:drop-shadow(0 22px 55px rgba(0,0,0,.56)) drop-shadow(0 0 44px rgba(255,208,151,.14))!important;animation:cellDrift 9s ease-in-out infinite!important}}
.presence svg{{opacity:.05!important;transform:scale(.74)!important}}
.cell-life{{position:absolute;z-index:4;left:50%;top:46%;transform:translate(-50%,-50%);width:min(33vw,290px);aspect-ratio:1;border-radius:47% 53% 49% 51% / 52% 44% 56% 48%;pointer-events:none;background:radial-gradient(circle at 48% 46%,rgba(255,246,225,.98) 0 1.8%,rgba(255,222,180,.82) 3.2%,rgba(233,203,181,.18) 11%,rgba(120,130,150,.08) 38%,rgba(20,22,24,.02) 61%),radial-gradient(circle at 50% 50%,rgba(255,255,255,.12),rgba(255,255,255,.015) 63%,transparent 70%);border:1px solid rgba(255,238,214,.31);box-shadow:inset 0 0 38px rgba(255,238,220,.12),inset 18px 6px 54px rgba(130,105,145,.13),0 0 30px rgba(255,188,130,.12),0 0 90px rgba(124,135,170,.09);backdrop-filter:blur(2px);animation:cellMorph 7.8s ease-in-out infinite,cellFloat 11s ease-in-out infinite}}
.cell-life:before,.cell-life:after{{content:'';position:absolute;border-radius:50%;pointer-events:none}}
.cell-life:before{{inset:12%;border:1px solid rgba(255,224,198,.22);box-shadow:0 0 22px rgba(255,205,161,.08),inset 0 0 20px rgba(255,255,255,.08);background:repeating-conic-gradient(from 0deg,rgba(255,255,255,.08) 0 1deg,transparent 1deg 14deg);filter:blur(.35px);animation:cellSpin 19s linear infinite}}
.cell-life:after{{inset:28%;background:radial-gradient(circle,rgba(255,250,232,.75),rgba(255,194,139,.2) 18%,rgba(121,112,155,.08) 42%,transparent 68%);filter:blur(3px);animation:corePulse 3.8s ease-in-out infinite}}
.filaments{{position:absolute;z-index:5;left:50%;top:46%;transform:translate(-50%,-50%);width:min(43vw,365px);aspect-ratio:1;border-radius:50%;pointer-events:none;opacity:.66;background:repeating-conic-gradient(from 10deg,transparent 0 8deg,rgba(255,225,195,.14) 9deg,transparent 10deg 19deg);mask-image:radial-gradient(circle,black 0 52%,transparent 69%);animation:filamentBreath 6.4s ease-in-out infinite,cellSpin 31s linear infinite reverse}}
.vesicle{{position:absolute;z-index:5;width:7px;height:7px;border-radius:50%;background:rgba(255,228,194,.72);box-shadow:0 0 14px rgba(255,211,160,.46);pointer-events:none;animation:vesicle 8s ease-in-out infinite}}
.v1{{left:43%;top:35%;animation-delay:-2s}}.v2{{left:59%;top:41%;animation-delay:-5s;width:4px;height:4px}}.v3{{left:53%;top:58%;animation-delay:-1s;width:5px;height:5px}}.v4{{left:40%;top:52%;animation-delay:-6s;width:3px;height:3px}}
@keyframes cellMorph{{0%,100%{{border-radius:47% 53% 49% 51%/52% 44% 56% 48%;filter:saturate(.9)}}35%{{border-radius:52% 48% 44% 56%/47% 57% 43% 53%;filter:saturate(1.04)}}68%{{border-radius:43% 57% 55% 45%/56% 46% 54% 44%;filter:saturate(.96)}}}}
@keyframes cellFloat{{0%,100%{{transform:translate(-50%,-50%) translateY(0) rotate(-1deg) scale(.985)}}50%{{transform:translate(-50%,-50%) translateY(-9px) rotate(1.2deg) scale(1.02)}}}}
@keyframes cellSpin{{to{{transform:rotate(360deg)}}}}
@keyframes corePulse{{0%,100%{{transform:scale(.86);opacity:.55}}50%{{transform:scale(1.16);opacity:1}}}}
@keyframes filamentBreath{{0%,100%{{transform:scale(.92);opacity:.38}}50%{{transform:scale(1.08);opacity:.82}}}}
@keyframes vesicle{{0%,100%{{transform:translate(0,0) scale(.75);opacity:.35}}45%{{transform:translate(14px,-11px) scale(1.25);opacity:.9}}70%{{transform:translate(-7px,7px) scale(.9);opacity:.55}}}}
@keyframes cellDrift{{0%,100%{{transform:translateY(0)}}50%{{transform:translateY(-5px)}}}}
.presence.listening~.cell-life,.room[data-m4-state='listening'] .cell-life{{animation-duration:5.1s,7.2s;box-shadow:inset 0 0 44px rgba(255,243,228,.16),0 0 42px rgba(255,188,130,.18),0 0 110px rgba(120,140,180,.13)}}
.room[data-m4-state='thinking'] .cell-life{{transform:translate(-50%,-50%) scale(.94);filter:contrast(1.08) saturate(1.08)}}
.room[data-m4-state='thinking'] .filaments{{animation-duration:2.7s,12s;opacity:.9}}
.room[data-m4-state='speaking'] .cell-life{{animation-duration:2.2s,5s;box-shadow:inset 0 0 56px rgba(255,245,228,.21),0 0 55px rgba(255,186,125,.24),0 0 135px rgba(142,126,180,.18)}}
.room[data-m4-state='speaking'] .cell-life:after{{animation-duration:1.1s}}
.room[data-m4-state='speaking'] .filaments{{animation-duration:1.5s,15s;opacity:.95}}
.status{{z-index:8!important;bottom:max(24px,calc(env(safe-area-inset-bottom) + 18px))!important;padding:10px 18px!important;border-radius:999px!important;background:rgba(10,10,10,.5)!important;border:1px solid rgba(255,255,255,.14)!important;backdrop-filter:blur(14px)!important;box-shadow:0 14px 36px rgba(0,0,0,.34)!important;width:auto!important;min-width:min(84vw,360px)!important}}
.state{{color:rgba(255,245,231,.72)!important;font-size:9px!important;letter-spacing:.22em!important}}
.hint{{color:rgba(255,245,231,.78)!important;font-size:13px!important}}
.control{{background:rgba(8,8,8,.46)!important;color:rgba(255,245,231,.8)!important;border-color:rgba(255,255,255,.14)!important;backdrop-filter:blur(12px)!important}}
.enter{{background:rgba(6,6,6,.46)!important;backdrop-filter:blur(10px)!important}}
.enter button{{background:rgba(12,12,12,.7)!important;color:#fff4e5!important;border-color:rgba(255,255,255,.18)!important;box-shadow:0 18px 60px rgba(0,0,0,.46)!important}}
.ambient-label{{position:absolute;left:20px;top:max(20px,env(safe-area-inset-top));z-index:8;font:500 9px ui-monospace,SFMono-Regular,monospace;letter-spacing:.18em;color:rgba(255,243,226,.46);text-transform:uppercase;pointer-events:none}}
@media(max-width:650px){{.cell-life{{width:min(54vw,245px);top:44%}}.filaments{{width:min(68vw,310px);top:44%}}.presence{{width:82vw!important;height:82vw!important}}.status{{min-width:86vw!important}}}}
</style>
'''

VISUAL_JS = r'''
<script id="m4-alive-v4">
(function(){
 const room=document.getElementById('room'); if(!room)return;
 const cell=document.createElement('div');cell.className='cell-life';room.appendChild(cell);
 const fil=document.createElement('div');fil.className='filaments';room.appendChild(fil);
 ['v1','v2','v3','v4'].forEach(c=>{const v=document.createElement('div');v.className='vesicle '+c;room.appendChild(v)});
 const label=document.createElement('div');label.className='ambient-label';label.textContent='M4 / PRESENT';room.appendChild(label);
 const originalVisual=window.visual;
 if(typeof originalVisual==='function'){window.visual=function(s,msg){originalVisual(s,msg);room.dataset.m4State=s||'present';label.textContent='M4 / '+String(s||'present').toUpperCase();}};
 let enhanced=false,noise=null,low=null,breathTimer=null;
 function startExtraAmbience(){
  if(enhanced||!window.audioCtx||!window.master)return; enhanced=true; const ctx=window.audioCtx;
  try{
   const b=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),d=b.getChannelData(0);let last=0;
   for(let i=0;i<d.length;i++){const w=Math.random()*2-1;last=last*.992+w*.008;d[i]=last*.44}
   const src=ctx.createBufferSource();src.buffer=b;src.loop=true;const lp=ctx.createBiquadFilter();lp.type='lowpass';lp.frequency.value=180;const g=ctx.createGain();g.gain.value=.045;src.connect(lp).connect(g).connect(window.master);src.start();noise=src;
   low=ctx.createOscillator();low.type='sine';low.frequency.value=32;const lg=ctx.createGain();lg.gain.value=.045;low.connect(lg).connect(window.master);low.start();
   function breathe(){const t=ctx.currentTime;lg.gain.cancelScheduledValues(t);lg.gain.setValueAtTime(.032,t);lg.gain.linearRampToValueAtTime(.06,t+2.6);lg.gain.linearRampToValueAtTime(.032,t+5.4)} breathe();breathTimer=setInterval(breathe,5600);
  }catch(e){console.log('M4 ambience enhancement unavailable',e)}
 }
 const oa=window.ambient;if(typeof oa==='function'){window.ambient=function(){oa();try{if(window.master)window.master.gain.value=.17;startExtraAmbience()}catch(e){}}}
})();
</script>
'''


def enhance(html: str) -> str:
    if 'id="m4-presentation-v4"' in html:
        return html
    html = html.replace('</head>', VISUAL_CSS + '</head>')
    html = html.replace('</body>', VISUAL_JS + '</body>')
    return html
